def reverse_string(s):
    """Return the characters of s in reverse order."""
    # Reject non-string input early so slicing cannot fail silently on bytes or lists.
    if not isinstance(s, str):
        raise TypeError("reverse_string expects a str, got %s" % type(s).__name__)
    # Slicing with a negative step is the fastest way to reverse a Python string.
    return s[::-1]


def reverse_words(sentence):
    """Reverse the order of whitespace-separated words, keeping each word intact."""
    words = sentence.split()
    # An empty or whitespace-only sentence has no words to reorder.
    if not words:
        return ""
    words.reverse()
    return " ".join(words)


def reverse_each_word(sentence):
    """Reverse the letters inside every word but keep the words in place."""
    return " ".join(reverse_string(word) for word in sentence.split())


def is_palindrome(s, ignore_case=True, ignore_non_alnum=True):
    """Report whether s reads the same forwards and backwards."""
    cleaned = s
    if ignore_non_alnum:
        # Punctuation and spaces should not break a phrase palindrome.
        cleaned = "".join(ch for ch in cleaned if ch.isalnum())
    if ignore_case:
        cleaned = cleaned.casefold()
    return cleaned == reverse_string(cleaned)


def format_report(s):
    """Build a multi-line human-readable summary of the reversals of s."""
    lines = ["input:            %r" % s,
             "reversed:         %r" % reverse_string(s),
             "words reversed:   %r" % reverse_words(s),
             "letters reversed: %r" % reverse_each_word(s)]
    # Only mention the palindrome property when the string actually is one.
    if is_palindrome(s):
        lines.append("note:             this text is a palindrome")
    return "\n".join(lines)


def main(argv=None):
    import sys

    argv = sys.argv[1:] if argv is None else list(argv)
    # Fall back to a small built-in set of samples when no arguments are given.
    if not argv:
        argv = ["hello", "Python", "A man, a plan, a canal: Panama", "never odd or even"]

    for index, text in enumerate(argv):
        # Separate consecutive reports with a blank line for readability.
        if index:
            print()
        print(format_report(text))

    return 0


if __name__ == "__main__":
    raise SystemExit(main())

