VOWELS = frozenset("aeiou")


def count_vowels(text):
    """Return the number of vowels (a, e, i, o, u) in text, ignoring case."""
    # Reject non-string input early so callers get a clear error message.
    if not isinstance(text, str):
        raise TypeError("count_vowels() expects a string, got %r" % type(text).__name__)
    total = 0
    for ch in text.lower():
        # Only ASCII vowels count; digits, spaces and punctuation are skipped.
        if ch in VOWELS:
            total += 1
    return total


def vowel_frequencies(text):
    """Return a dict mapping each vowel to how often it appears in text."""
    counts = {vowel: 0 for vowel in "aeiou"}
    for ch in text.lower():
        if ch in counts:
            counts[ch] += 1
    return counts


def vowel_ratio(text):
    """Return the fraction of alphabetic characters in text that are vowels."""
    letters = sum(1 for ch in text if ch.isalpha())
    # An empty or symbol-only string has no letters, so the ratio is zero.
    if letters == 0:
        return 0.0
    return count_vowels(text) / letters


def most_common_vowel(text):
    """Return the most frequent vowel in text, or None if there are none."""
    frequencies = vowel_frequencies(text)
    best = None
    for vowel in "aeiou":
        # Ties are resolved in alphabetical order because of the strict >.
        if best is None or frequencies[vowel] > frequencies[best]:
            best = vowel
    if frequencies[best] == 0:
        return None
    return best


def describe(text):
    """Build a one-line human readable report about the vowels in text."""
    total = count_vowels(text)
    breakdown = vowel_frequencies(text)
    parts = []
    for vowel in "aeiou":
        # Mentioning vowels that never occur would only clutter the report.
        if breakdown[vowel]:
            parts.append("%s=%d" % (vowel, breakdown[vowel]))
    detail = ", ".join(parts) if parts else "none"
    top = most_common_vowel(text)
    top_text = top if top is not None else "-"
    return "%-14r total=%d [%s] top=%s ratio=%.2f" % (
        text,
        total,
        detail,
        top_text,
        vowel_ratio(text),
    )


def main():
    samples = ["Hello World", "Python", "AEIOU aeiou", "rhythm", "", "42!"]
    for sample in samples:
        print(describe(sample))
    # Summarise the whole batch so the driver reports something aggregate too.
    grand_total = sum(count_vowels(sample) for sample in samples)
    print("Vowels across %d samples: %d" % (len(samples), grand_total))


if __name__ == "__main__":
    main()

