"""Temperature conversion utilities (Celsius to Fahrenheit)."""

ABSOLUTE_ZERO_C = -273.15


def celsius_to_fahrenheit(celsius):
    """Convert a Celsius temperature to Fahrenheit."""
    # reject values that only look numeric, such as True or a string.
    if isinstance(celsius, bool) or not isinstance(celsius, (int, float)):
        raise TypeError("celsius must be a real number")
    return celsius * 9 / 5 + 32


def parse_celsius(text):
    """Read a Celsius value from text such as '25', '-4.5C' or '12 °c'."""
    cleaned = text.strip().replace("°", "").strip()
    # trailing unit letters are optional, so remove one before parsing.
    if cleaned[-1:] in ("C", "c"):
        cleaned = cleaned[:-1].strip()
    if not cleaned:
        raise ValueError("no temperature found in %r" % text)
    try:
        return float(cleaned)
    except ValueError:
        raise ValueError("cannot read %r as a Celsius temperature" % text)


def is_physically_valid(celsius):
    """Report whether a reading sits at or above absolute zero."""
    return celsius >= ABSOLUTE_ZERO_C


def format_conversion(celsius, digits=1):
    """Build a one-line human readable description of a single conversion."""
    fahrenheit = celsius_to_fahrenheit(celsius)
    line = "{:.{d}f} °C = {:.{d}f} °F".format(celsius, fahrenheit, d=digits)
    # readings colder than absolute zero get flagged rather than hidden.
    if not is_physically_valid(celsius):
        line += "  (below absolute zero!)"
    return line


def conversion_table(readings, digits=1):
    """Convert a sequence of textual readings into formatted report lines."""
    lines = []
    for raw in readings:
        # keep going after a bad entry so one typo does not lose the batch.
        try:
            celsius = parse_celsius(raw)
        except ValueError as exc:
            lines.append("skipped %r: %s" % (raw, exc))
            continue
        lines.append(format_conversion(celsius, digits))
    return lines


def summarize(readings):
    """Return the warmest Fahrenheit value among the usable readings."""
    values = []
    for raw in readings:
        try:
            celsius = parse_celsius(raw)
        except ValueError:
            continue
        # impossible readings must not influence the reported maximum.
        if is_physically_valid(celsius):
            values.append(celsius_to_fahrenheit(celsius))
    if not values:
        raise ValueError("no usable readings")
    return max(values)


def main():
    readings = ["0", "25", "-40", "100", "37.5 C", "-300°C", "warm"]
    for line in conversion_table(readings):
        print(line)
    print("warmest: %.1f °F" % summarize(readings))


if __name__ == "__main__":
    main()

