MONTH_LENGTHS = (31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31)


def is_leap_year(year):
    # Gregorian rule: every 4th year, except centuries not divisible by 400.
    return year % 4 == 0 and (year % 100 != 0 or year % 400 == 0)


def days_in_month(year, month):
    if month < 1 or month > 12:
        raise ValueError(f"month out of range: {month}")
    # February gains a day in leap years.
    if month == 2 and is_leap_year(year):
        return 29
    return MONTH_LENGTHS[month - 1]


def validate_date(year, month, day):
    # All three components must be plain integers, not floats or strings.
    for name, value in (("year", year), ("month", month), ("day", day)):
        if isinstance(value, bool) or not isinstance(value, int):
            raise TypeError(f"{name} must be an int, got {type(value).__name__}")
    # Years outside this range cannot be zero-padded to exactly four digits.
    if year < 1 or year > 9999:
        raise ValueError(f"year out of range: {year}")
    limit = days_in_month(year, month)
    if day < 1 or day > limit:
        raise ValueError(f"day out of range for {year}-{month}: {day}")


def format_date(year, month, day):
    """Return the date as a zero-padded 'YYYY-MM-DD' string."""
    validate_date(year, month, day)
    # The f-string width specifiers do the zero-padding.
    return f"{year:04d}-{month:02d}-{day:02d}"


def parse_date(text):
    """Turn a 'YYYY-MM-DD' string back into a (year, month, day) tuple."""
    parts = text.split("-")
    if len(parts) != 3:
        raise ValueError(f"expected YYYY-MM-DD, got {text!r}")
    try:
        year, month, day = (int(part) for part in parts)
    except ValueError:
        raise ValueError(f"non-numeric component in {text!r}") from None
    validate_date(year, month, day)
    return year, month, day


def format_range(start, end):
    """Format two (year, month, day) tuples as a single hyphenated range."""
    first = format_date(*start)
    last = format_date(*end)
    # Keep the range in chronological order regardless of argument order.
    if first > last:
        first, last = last, first
    return f"{first} .. {last}"


def main():
    samples = [(2023, 7, 15), (2020, 1, 1), (2024, 2, 29), (1999, 12, 31)]
    for sample in samples:
        print(format_date(*sample))
    print(format_range(samples[0], samples[1]))
    # Round-tripping proves the formatter and parser agree.
    text = format_date(2024, 2, 29)
    print(parse_date(text))
    # Invalid dates are reported rather than silently formatted.
    for bad in [(2023, 2, 29), (2023, 13, 1), (2023, 4, 0)]:
        try:
            format_date(*bad)
        except ValueError as exc:
            print(f"rejected {bad}: {exc}")


if __name__ == "__main__":
    main()

