def update_inventory(inventory, item_name, quantity):
    """Add quantity to item_name in inventory, creating the entry if needed."""
    if not isinstance(inventory, dict):
        raise TypeError("inventory must be a dictionary")
    if not isinstance(item_name, str) or not item_name.strip():
        raise ValueError("item_name must be a non-empty string")
    if not isinstance(quantity, int) or isinstance(quantity, bool):
        raise TypeError("quantity must be an integer")

    key = item_name.strip()
    # Missing items start from zero so the same addition works in both cases
    current = inventory.get(key, 0)
    inventory[key] = current + quantity
    return inventory


def remove_item(inventory, item_name):
    """Drop an item completely and return the quantity that was held."""
    key = item_name.strip()
    # Popping with a default keeps removal of unknown items harmless
    return inventory.pop(key, 0)


def apply_transactions(inventory, transactions):
    """Apply (name, quantity) pairs in order, dropping items that hit zero."""
    for item_name, quantity in transactions:
        update_inventory(inventory, item_name, quantity)
        key = item_name.strip()
        # Negative stock is meaningless, so clamp it before deciding to remove
        if inventory[key] <= 0:
            remove_item(inventory, key)
    return inventory


def total_units(inventory):
    """Sum every quantity currently stored."""
    return sum(inventory.values())


def low_stock(inventory, threshold):
    """Return the names of items at or below threshold, alphabetically."""
    # Sorting makes the report stable regardless of insertion order
    return sorted(name for name, qty in inventory.items() if qty <= threshold)


def format_report(inventory, threshold=5):
    """Build a human readable stock report as a single string."""
    lines = []
    width = max((len(name) for name in inventory), default=4)
    for name in sorted(inventory):
        lines.append("{0:<{1}}  {2:>5}".format(name, width, inventory[name]))
    lines.append("-" * (width + 7))
    lines.append("{0:<{1}}  {2:>5}".format("TOTAL", width, total_units(inventory)))
    scarce = low_stock(inventory, threshold)
    # Only mention restocking when something actually ran low
    if scarce:
        lines.append("Low stock: " + ", ".join(scarce))
    return "\n".join(lines)


def main():
    inventory = {'apple': 10}
    print(update_inventory(dict(inventory), 'apple', 5))
    print(update_inventory(dict(inventory), 'banana', 3))

    deliveries = [('banana', 3), ('cherry', 12), ('apple', 5), (' banana ', 2)]
    apply_transactions(inventory, deliveries)

    # Shipping out more apples than requested would empty the bin entirely
    sales = [('apple', -12), ('cherry', -8)]
    apply_transactions(inventory, sales)

    print(format_report(inventory))


if __name__ == "__main__":
    main()

