VALID_CHOICES = ('rock', 'paper', 'scissors')

# Each key beats its mapped value, which fully describes the game's rules.
BEATS = {'rock': 'scissors', 'paper': 'rock', 'scissors': 'paper'}

TIE = "It's a tie!"
P1_WINS = 'Player 1 wins!'
P2_WINS = 'Player 2 wins!'


def normalize(choice):
    """Return a cleaned, lower-case choice, rejecting anything unplayable."""
    if not isinstance(choice, str):
        raise TypeError('choice must be a string, got %r' % (choice,))
    cleaned = choice.strip().lower()
    # Players often type extra spaces or capitals, so compare after cleaning.
    if cleaned not in VALID_CHOICES:
        raise ValueError('invalid choice: %r' % (choice,))
    return cleaned


def rock_paper_scissors(player1_choice, player2_choice):
    """Play one round and report the outcome as a human-readable string."""
    first = normalize(player1_choice)
    second = normalize(player2_choice)
    # Identical choices cancel out before any winner is determined.
    if first == second:
        return TIE
    # Player 1 wins exactly when their choice beats player 2's choice.
    if BEATS[first] == second:
        return P1_WINS
    return P2_WINS


def play_match(rounds):
    """Score a sequence of (player1, player2) rounds and return the tallies."""
    score = {'player1': 0, 'player2': 0, 'ties': 0}
    for player1_choice, player2_choice in rounds:
        result = rock_paper_scissors(player1_choice, player2_choice)
        # Translate the message back into the counter it belongs to.
        if result == P1_WINS:
            score['player1'] += 1
        elif result == P2_WINS:
            score['player2'] += 1
        else:
            score['ties'] += 1
    return score


def format_round(player1_choice, player2_choice):
    """Build a one-line report for a single round."""
    result = rock_paper_scissors(player1_choice, player2_choice)
    return '%-8s vs %-8s -> %s' % (player1_choice, player2_choice, result)


def describe_match(score):
    """Summarise a match score, naming the overall winner if there is one."""
    lines = ['Player 1: %d' % score['player1'],
             'Player 2: %d' % score['player2'],
             'Ties: %d' % score['ties']]
    # The match leader is whoever won strictly more rounds.
    if score['player1'] > score['player2']:
        lines.append('Match winner: Player 1')
    elif score['player2'] > score['player1']:
        lines.append('Match winner: Player 2')
    else:
        lines.append('Match drawn')
    return '\n'.join(lines)


def main():
    rounds = [('rock', 'scissors'), ('paper', 'rock'), ('Scissors', ' scissors'),
              ('rock', 'paper'), ('scissors', 'paper')]
    for player1_choice, player2_choice in rounds:
        print(format_round(player1_choice, player2_choice))
    print(describe_match(play_match(rounds)))


if __name__ == '__main__':
    main()

