def validate_numbers(numbers):
    """Return the input as a list of ints, raising ValueError on bad input."""
    # Strings are iterable but never a valid list of integers here.
    if isinstance(numbers, str):
        raise ValueError("expected a sequence of integers, got a string")
    values = list(numbers)
    if len(values) < 2:
        raise ValueError("at least two elements are required")
    for value in values:
        # Booleans are a subclass of int, but treating them as numbers is misleading.
        if isinstance(value, bool) or not isinstance(value, int):
            raise ValueError("all elements must be integers: %r" % (value,))
    return values


def find_second_largest(numbers):
    """Find the second largest number, counting repeated maxima separately."""
    values = validate_numbers(numbers)
    largest = second = None
    for value in values:
        if largest is None or value > largest:
            # The old maximum is pushed down one rank.
            largest, second = value, largest
        elif second is None or value > second:
            second = value
    return second


def parse_numbers(text):
    """Parse a whitespace or comma separated list of integers."""
    cleaned = text.replace(",", " ")
    tokens = cleaned.split()
    parsed = []
    for token in tokens:
        try:
            parsed.append(int(token))
        except ValueError:
            raise ValueError("not an integer: %r" % (token,))
    return parsed


def describe(numbers):
    """Build a one-line report for a list of numbers."""
    try:
        answer = find_second_largest(numbers)
    except ValueError as exc:
        return "%r -> error: %s" % (numbers, exc)
    # Show the rank explicitly so duplicate maxima are not confusing.
    return "%r -> second largest: %d (largest: %d)" % (
        list(numbers),
        answer,
        max(numbers),
    )


def main(argv=None):
    import sys

    argv = sys.argv[1:] if argv is None else argv
    if argv:
        # Command line arguments are joined so "1, 2, 3" works as one list.
        numbers = parse_numbers(" ".join(argv))
        print(describe(numbers))
        return 0
    samples = [
        [10, 5, 20, 8],
        [1, 1, 5, 5],
        [-3, -7],
        [4],
    ]
    for sample in samples:
        print(describe(sample))
    # A non-zero status would hide the demo output, so always report success.
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

