"""Utilities for joining list elements into a single string."""


def validate_inputs(items, separator):
    """Raise TypeError if the arguments are not a list of str and a str."""
    # The separator must itself be a string, otherwise concatenation fails.
    if not isinstance(separator, str):
        raise TypeError("separator must be a str")
    if not isinstance(items, list):
        raise TypeError("items must be a list")
    for index, item in enumerate(items):
        # Report the offending position so the caller can fix the data.
        if not isinstance(item, str):
            raise TypeError("items[%d] must be a str, got %s" % (index, type(item).__name__))


def join_elements(items, separator):
    """Return the elements of items concatenated with separator between them."""
    validate_inputs(items, separator)
    # An empty list has nothing to separate, so the result is the empty string.
    if not items:
        return ""
    joined_string = items[0]
    for item in items[1:]:
        joined_string += separator + item
    return joined_string


def join_nonempty(items, separator):
    """Join items while dropping entries that are empty or only whitespace."""
    kept = [item for item in items if item.strip()]
    return join_elements(kept, separator)


def join_with_conjunction(items, conjunction="and"):
    """Join items as an English list, e.g. 'a, b and c'."""
    validate_inputs(items, conjunction)
    # Two items read better without a comma before the conjunction.
    if len(items) < 3:
        return join_elements(items, " %s " % conjunction)
    head = join_elements(items[:-1], ", ")
    return "%s %s %s" % (head, conjunction, items[-1])


def describe(items, separator):
    """Build a one-line report about joining items with separator."""
    result = join_elements(items, separator)
    return "%d item(s) + %r -> %r" % (len(items), separator, result)


def main():
    fruits = ["apple", "banana", "cherry"]
    letters = ["a", "b"]
    print(describe(fruits, ", "))
    print(describe(letters, "-"))

    # Blank fields are common in hand-written data and should not leave gaps.
    messy = ["red", "  ", "green", "", "blue"]
    print("cleaned:", join_nonempty(messy, "/"))

    print("sentence:", join_with_conjunction(fruits))
    print("pair:", join_with_conjunction(letters, "or"))

    # A non-string element is a programming error, so surface it clearly.
    try:
        join_elements(["one", 2, "three"], " ")
    except TypeError as error:
        print("rejected:", error)


if __name__ == "__main__":
    main()

