"""Utilities for counting lines (and related stats) in text files."""

import os
import sys


def count_file_lines(filepath):
    """Return the number of lines in the file at *filepath*."""
    line_count = 0
    ends_with_newline = True
    # Read in binary chunks so that huge files never have to be held in memory.
    with open(filepath, "rb") as handle:
        while True:
            chunk = handle.read(1 << 16)
            if not chunk:
                break
            line_count += chunk.count(b"\n")
            ends_with_newline = chunk.endswith(b"\n")
    # A final line without a terminator still counts as a line.
    if not ends_with_newline:
        line_count += 1
    return line_count


def count_file_words(filepath, encoding="utf-8"):
    """Return the number of whitespace-separated words in the file."""
    word_count = 0
    # Undecodable bytes are replaced instead of raising an error.
    with open(filepath, "r", encoding=encoding, errors="replace") as handle:
        for line in handle:
            word_count += len(line.split())
    return word_count


def file_stats(filepath, encoding="utf-8"):
    """Collect line, word and byte counts for a single file."""
    # Byte size comes from the filesystem, which avoids a third pass.
    return {
        "path": filepath,
        "lines": count_file_lines(filepath),
        "words": count_file_words(filepath, encoding),
        "bytes": os.path.getsize(filepath),
    }


def format_stats(stats):
    """Format one stats mapping as a right-aligned report row."""
    return "{lines:>8} {words:>8} {bytes:>10}  {path}".format(**stats)


def report(filepaths, encoding="utf-8"):
    """Build a report for several files, ending with a total row."""
    rows = []
    totals = {"path": "total", "lines": 0, "words": 0, "bytes": 0}
    for path in filepaths:
        stats = file_stats(path, encoding)
        rows.append(format_stats(stats))
        # Accumulate every numeric field of the current file into the totals.
        for key in ("lines", "words", "bytes"):
            totals[key] += stats[key]
    # The summary row is only meaningful when more than one file was read.
    if len(filepaths) > 1:
        rows.append(format_stats(totals))
    return "\n".join(rows)


def main(argv):
    """Print a line/word/byte report for the files named on the command line."""
    if len(argv) < 2:
        print("usage: {} FILE [FILE ...]".format(os.path.basename(argv[0])))
        return 2
    # Header uses the same column widths as the data rows.
    print("{:>8} {:>8} {:>10}  {}".format("lines", "words", "bytes", "file"))
    print(report(argv[1:]))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))

