def _validate(name, value):
    """Raise TypeError unless value is a dict, naming the offending argument."""
    if not isinstance(value, dict):
        # Mapping semantics are required, so reject anything else up front.
        raise TypeError(f"{name} must be a dict, got {type(value).__name__}")
    return value


def update_dict(dict1, dict2):
    """Merge dict2 into dict1 and return the result without mutating the inputs."""
    _validate("dict1", dict1)
    _validate("dict2", dict2)
    # Copy first so the caller's original dictionary stays untouched.
    merged_dict = dict(dict1)
    merged_dict.update(dict2)
    return merged_dict


def update_dict_deep(dict1, dict2):
    """Like update_dict, but nested dictionaries are merged recursively."""
    _validate("dict1", dict1)
    _validate("dict2", dict2)
    merged_dict = dict(dict1)
    for key, new_value in dict2.items():
        old_value = merged_dict.get(key)
        # Two dicts under the same key describe the same subtree, so recurse.
        if isinstance(old_value, dict) and isinstance(new_value, dict):
            merged_dict[key] = update_dict_deep(old_value, new_value)
        else:
            merged_dict[key] = new_value
    return merged_dict


def classify_keys(dict1, dict2):
    """Return (unchanged, overridden, added) key lists in sorted order."""
    keys1, keys2 = set(dict1), set(dict2)
    # Overridden keys exist in both but carry a different value.
    overridden = [k for k in keys1 & keys2 if dict1[k] != dict2[k]]
    unchanged = [k for k in keys1 if k not in keys2]
    added = list(keys2 - keys1)
    return sorted(unchanged), sorted(overridden), sorted(added)


def format_report(dict1, dict2):
    """Build a human readable summary of what merging dict2 into dict1 does."""
    merged = update_dict(dict1, dict2)
    unchanged, overridden, added = classify_keys(dict1, dict2)
    lines = [f"merged: {merged}"]
    # Only mention categories that actually contain keys.
    if unchanged:
        lines.append("  kept:      " + ", ".join(map(str, unchanged)))
    for key in overridden:
        lines.append(f"  updated:   {key}: {dict1[key]!r} -> {dict2[key]!r}")
    if added:
        lines.append("  added:     " + ", ".join(map(str, added)))
    return "\n".join(lines)


def main():
    base = {"host": "localhost", "port": 8080, "debug": False}
    override = {"port": 9090, "debug": True, "workers": 4}
    print(format_report(base, override))
    # The originals must survive the merge unchanged.
    print("base after merge:", base)

    defaults = {"db": {"host": "localhost", "port": 5432}, "retries": 3}
    user = {"db": {"port": 6543, "user": "admin"}}
    # A shallow merge would drop db.host, so use the recursive variant here.
    print("deep:", update_dict_deep(defaults, user))
    print("shallow:", update_dict(defaults, user))


if __name__ == "__main__":
    main()

