    weeks, extra = divmod(days, 7)
    # only mention weeks once there is at least one full week to report.
    if weeks:
        breakdown = " = %d week(s) and %d day(s)" % (weeks, extra)
    else:
        breakdown = ""

    return "%d day(s) remaining until %s%s" % (days, end_date_str, breakdown)


def main():
    schedule = [
        ('2023-01-01', '2023-01-05'),
        ('2023-12-31', '2024-01-01'),
        ('2024-02-28', '2024-03-01'),
        ('2024-06-01', '2024-05-01'),
        ('2025-03-10', '2025-03-10'),
    ]

    for start_str, end_str in schedule:
        # bad rows should not abort the whole report, so handle them per pair.
        try:
            print(describe_remaining(start_str, end_str))
        except (TypeError, ValueError) as exc:
            print("skipping (%s, %s): %s" % (start_str, end_str, exc))

    total = sum(days_remaining(s, e) for s, e in schedule)
    # the net total can cancel out when past dates are mixed with future ones.
    print("net day balance across the schedule: %d" % total)


if __name__ == '__main__':
    main()

