ALPHABET = "abcdefghijklmnopqrstuvwxyz"

COMMON_WORDS = frozenset({
    "the", "there", "hello", "world", "and", "is", "was", "secret",
    "message", "attack", "dawn", "meet", "at", "you", "this",
})


def normalize_shift(shift):
    # Shifts repeat every 26 letters, so reduce to the canonical range.
    return shift % len(ALPHABET)


def decrypt_caesar(text, shift):
    """Undo a Caesar cipher applied to lowercase English letters."""
    if not isinstance(text, str):
        raise TypeError("text must be a string")
    # A float shift would break modular arithmetic on character indices.
    if not isinstance(shift, int):
        raise TypeError("shift must be an integer")
    key = normalize_shift(shift)
    decrypted_chars = []
    for char in text:
        if char in ALPHABET:
            index = (ALPHABET.index(char) - key) % len(ALPHABET)
            decrypted_chars.append(ALPHABET[index])
        else:
            # Spaces, digits and punctuation are carried over untouched.
            decrypted_chars.append(char)
    return "".join(decrypted_chars)


def encrypt_caesar(text, shift):
    # Encryption is simply decryption with the opposite shift.
    return decrypt_caesar(text, -shift)


def score_plaintext(text):
    """Count how many whitespace-separated tokens look like English words."""
    score = 0
    for token in text.split():
        word = token.strip(".,!?;:'\"")
        if word in COMMON_WORDS:
            score += 1
    return score


def crack_caesar(text):
    """Return (shift, plaintext) for the most English-looking candidate."""
    best_shift = 0
    best_text = text
    best_score = -1
    for candidate_shift in range(len(ALPHABET)):
        candidate = decrypt_caesar(text, candidate_shift)
        current = score_plaintext(candidate)
        # Ties keep the smallest shift, which is found first.
        if current > best_score:
            best_shift = candidate_shift
            best_text = candidate
            best_score = current
    return best_shift, best_text


def format_report(ciphertext, shift):
    plaintext = decrypt_caesar(ciphertext, shift)
    return "{!r} with shift {} -> {!r}".format(ciphertext, shift, plaintext)


