"""Rectangle geometry helpers: area, perimeter and a command line reporter."""

import sys


def _validate_side(name, value):
    # Booleans are integers in Python, so they are rejected before the numeric test.
    if isinstance(value, bool) or not isinstance(value, (int, float)):
        raise TypeError("{} must be a real number, got {!r}".format(name, value))
    side = float(value)
    # A side of zero or less does not describe a rectangle.
    if side <= 0.0:
        raise ValueError("{} must be positive, got {}".format(name, side))
    return side


def rectangle_area(width, height):
    """Return the area of a rectangle with the given width and height."""
    w = _validate_side("width", width)
    h = _validate_side("height", height)
    return w * h


def rectangle_perimeter(width, height):
    """Return the perimeter of a rectangle with the given width and height."""
    w = _validate_side("width", width)
    h = _validate_side("height", height)
    return 2.0 * (w + h)


def is_square(width, height, tolerance=1e-9):
    """Report whether the two sides are equal within a small tolerance."""
    w = _validate_side("width", width)
    h = _validate_side("height", height)
    # Floating point sides rarely compare exactly, hence the tolerance.
    return abs(w - h) <= tolerance


def parse_dimensions(text):
    """Parse a 'width x height' string such as '2.5 x 4' into two floats."""
    # Both 'x' and '*' are common separators in typed dimensions.
    parts = text.lower().replace("*", "x").split("x")
    if len(parts) != 2:
        raise ValueError("expected 'width x height', got {!r}".format(text))
    numbers = []
    for part in parts:
        stripped = part.strip()
        try:
            numbers.append(float(stripped))
        except ValueError:
            raise ValueError("{!r} is not a number".format(stripped))
    return numbers[0], numbers[1]


def describe(width, height):
    """Build a one-line human readable summary of a rectangle."""
    area = rectangle_area(width, height)
    perimeter = rectangle_perimeter(width, height)
    shape = "square" if is_square(width, height) else "rectangle"
    # The 'g' format trims trailing zeros, so 50.0 prints as 50.
    return "{} {:g} x {:g}: area = {:g}, perimeter = {:g}".format(
        shape, width, height, area, perimeter
    )


def main(argv):
    if len(argv) < 2:
        print("usage: {} 'WIDTH x HEIGHT' ...".format(argv[0]))
        return 2
    status = 0
    for spec in argv[1:]:
        try:
            width, height = parse_dimensions(spec)
            print(describe(width, height))
        except (TypeError, ValueError) as exc:
            # A bad specification must not stop the remaining ones.
            print("{}: skipped ({})".format(spec, exc))
            status = 1
    return status


if __name__ == "__main__":
    sys.exit(main(sys.argv))

