def check_stock(inventory, items_to_check):
    # Create an empty dictionary to store the stock levels.
    stock_levels = {}
    # Iterate through each item that needs to be checked.
    for item in items_to_check:
        # Check if the current item exists in the inventory.
        if item in inventory:
            # If the item is in inventory, assign its quantity.
            stock_levels[item] = inventory[item]
        else:
            # Otherwise, the item is not available, so set its quantity to 0.
            stock_levels[item] = 0
    # The loop has processed all items.
    return stock_levels # Return the final dictionary of stock levels.

