"""Utilities for counting and summarising the words in a piece of text."""

from collections import Counter


def count_words(text):
    """Return the number of space-separated words in *text*."""
    # Reject anything that is not a string, since splitting would fail later.
    if not isinstance(text, str):
        raise TypeError("text must be a string")
    words = split_words(text)
    word_count = len(words)
    return word_count


def split_words(text):
    """Split *text* on runs of whitespace, dropping empty fragments."""
    words = []
    current = []
    for char in text:
        # Whitespace closes the word that is currently being collected.
        if char.isspace():
            if current:
                words.append("".join(current))
                current = []
        else:
            current.append(char)
    # The final word has no trailing separator, so flush it by hand.
    if current:
        words.append("".join(current))
    return words


def normalise(word):
    """Lower-case a word and strip the punctuation around it."""
    stripped = word.strip(".,;:!?\"'()[]{}")
    return stripped.lower()


def word_frequencies(text):
    """Map each normalised word of *text* to how often it occurs."""
    counts = Counter()
    for word in split_words(text):
        key = normalise(word)
        # Tokens made only of punctuation normalise to an empty string.
        if key:
            counts[key] += 1
    return counts


def format_report(text):
    """Build a human readable summary of the words found in *text*."""
    total = count_words(text)
    lines = ["words: {}".format(total)]
    frequencies = word_frequencies(text)
    # Sort by descending frequency, then alphabetically for stable output.
    ordered = sorted(frequencies.items(), key=lambda item: (-item[1], item[0]))
    for word, count in ordered:
        lines.append("  {:<12} {}".format(word, count))
    return "\n".join(lines)


def main():
    samples = [
        "This is a test sentence.",
        "  Hello   world  ",
        "the cat sat on the mat, the mat was flat",
    ]
    for sample in samples:
        print(repr(sample))
        print(format_report(sample))
        print()


if __name__ == "__main__":
    main()

