import random
from collections import Counter

DIE_FACES = 6


def roll_die():
    """Return the result of a single standard six-sided die roll."""
    # Both bounds are inclusive, so faces 1..6 are equally likely.
    return random.randint(1, DIE_FACES)


def simulate_dice_sum(num_dice):
    """Roll `num_dice` six-sided dice and return the sum of the faces."""
    # Booleans are a subclass of int, so reject them explicitly.
    if isinstance(num_dice, bool) or not isinstance(num_dice, int):
        raise TypeError("num_dice must be an integer")
    if num_dice < 0:
        raise ValueError("num_dice must be non-negative")

    total_sum = 0
    for _ in range(num_dice):
        total_sum += roll_die()
    # Zero dice legitimately fall through with a total of 0.
    return total_sum


def simulate_many(num_dice, trials):
    """Repeat the roll `trials` times and return the list of sums."""
    if trials < 1:
        raise ValueError("trials must be at least 1")
    return [simulate_dice_sum(num_dice) for _ in range(trials)]


def summarize(sums):
    """Compute min, max, mean and the frequency of each observed sum."""
    counts = Counter(sums)
    return {
        "min": min(sums),
        "max": max(sums),
        "mean": sum(sums) / len(sums),
        "counts": counts,
    }


def expected_mean(num_dice):
    """Return the theoretical average sum for `num_dice` fair dice."""
    # Each die averages (1 + 6) / 2, and the expectations add up.
    return num_dice * (DIE_FACES + 1) / 2


def format_histogram(counts, width=40):
    """Render the frequency table as a text histogram."""
    lines = []
    busiest = max(counts.values())
    # Sorting the keys puts the lowest possible sum on the first row.
    for value in sorted(counts):
        frequency = counts[value]
        bar_length = max(1, round(frequency * width / busiest))
        lines.append("{:>3} | {:<{w}} {}".format(value, "#" * bar_length, frequency, w=width))
    return "\n".join(lines)


def main():
    for num_dice in (1, 2, 5):
        print("simulate_dice_sum({}) -> {}".format(num_dice, simulate_dice_sum(num_dice)))

    trials = 2000
    dice = 3
    sums = simulate_many(dice, trials)
    stats = summarize(sums)

    print("\n{} dice, {} trials".format(dice, trials))
    print("min={min} max={max} mean={mean:.3f}".format(**stats))
    print("expected mean = {:.3f}".format(expected_mean(dice)))
    print(format_histogram(stats["counts"]))


if __name__ == "__main__":
    main()

