# Digit extraction helpers built around extract_numbers.

DIGITS = "0123456789"


def extract_numbers(text):
    """Return every digit found in *text*, concatenated in order of appearance."""
    # Reject non-string input so the caller gets a clear error.
    if not isinstance(text, str):
        raise TypeError("text must be a str, got " + type(text).__name__)
    found = []
    for char in text:
        # Only ASCII digits count; str.isdigit also accepts superscripts.
        if char in DIGITS:
            found.append(char)
    return "".join(found)


def split_numbers(text):
    """Return the maximal runs of consecutive digits in *text*."""
    runs = []
    current = ""
    for char in text:
        if char in DIGITS:
            current += char
        elif current:
            # A non-digit character terminates the run being collected.
            runs.append(current)
            current = ""
    # The text may end in the middle of a run.
    if current:
        runs.append(current)
    return runs


def digit_sum(text):
    """Return the sum of the individual digit values in *text*."""
    return sum(int(digit) for digit in extract_numbers(text))


def describe(text):
    """Build a one-line readable report about the digits in *text*."""
    digits = extract_numbers(text)
    if not digits:
        # Without digits there is nothing else to report.
        return "%r -> '' (no digits)" % (text,)
    values = ", ".join(str(int(run)) for run in split_numbers(text))
    return "%r -> %r  runs=[%s]  sum=%d" % (text, digits, values, digit_sum(text))


def main():
    samples = [
        "abc123def45",
        "No numbers here.",
        "007 phone: +44-20-7946-0958",
        "2024-06-01T09:30",
        "",
    ]
    for sample in samples:
        print(describe(sample))

    # Aggregate the digits of every sample into a single stream.
    combined = "".join(extract_numbers(sample) for sample in samples)
    print("combined:", combined)
    print("total digits:", len(combined))

    all_runs = [run for sample in samples for run in split_numbers(sample)]
    if all_runs:
        # Compare runs by numeric value, ignoring leading zeros.
        largest = max(all_runs, key=int)
        print("largest run:", largest, "->", int(largest))


if __name__ == "__main__":
    main()

