def count_char(text, char_to_count):
    """Return how many times char_to_count appears in text."""
    # Validate the types early so callers get a clear error instead of a wrong count
    if not isinstance(text, str) or not isinstance(char_to_count, str):
        raise TypeError("count_char expects two strings")
    # The search target must be exactly one character, otherwise counting is ambiguous
    if len(char_to_count) != 1:
        raise ValueError("char_to_count must be a single character")
    total = 0
    for character in text:
        if character == char_to_count:
            total += 1
    return total


def count_char_ignore_case(text, char_to_count):
    """Count occurrences of char_to_count without regard to letter case."""
    # Folding both sides keeps the single-character contract of count_char intact
    return count_char(text.casefold(), char_to_count.casefold())


def count_all_chars(text):
    """Return a dict mapping every character in text to its number of occurrences."""
    tally = {}
    for character in text:
        tally[character] = tally.get(character, 0) + 1
    return tally


def most_common_char(text):
    """Return the most frequent character in text, or None for an empty string."""
    tally = count_all_chars(text)
    if not tally:
        return None
    # Ties are broken by first appearance, so scan the original text order
    best = text[0]
    for character in text:
        if tally[character] > tally[best]:
            best = character
    return best


def format_report(text, char_to_count):
    """Build a one-line human readable summary for a single text/char pair."""
    exact = count_char(text, char_to_count)
    loose = count_char_ignore_case(text, char_to_count)
    line = "{!r}: {!r} appears {} time(s)".format(text, char_to_count, exact)
    # Only mention the case-insensitive figure when it adds information
    if loose != exact:
        line += " ({} ignoring case)".format(loose)
    return line


def main():
    samples = [
        ("banana", "a"),
        ("Mississippi", "s"),
        ("Hello World", "l"),
        ("Statistics", "S"),
    ]
    for text, char_to_count in samples:
        print(format_report(text, char_to_count))
    # Summarise the busiest character of each sample text as a closing overview
    for text, _char in samples:
        winner = most_common_char(text)
        print("{!r} is dominated by {!r} ({} times)".format(
            text, winner, count_char(text, winner)))


if __name__ == "__main__":
    main()

