def merge_dicts(dict1, dict2):
    """Return a new dict with dict2's values overriding dict1's on shared keys."""
    # Validate inputs so a wrong type fails here instead of deep inside the merge.
    if not isinstance(dict1, dict) or not isinstance(dict2, dict):
        raise TypeError("merge_dicts expects two dictionaries")
    merged = dict(dict1)
    merged.update(dict2)
    return merged


def merge_all(dicts):
    """Merge a sequence of dictionaries left to right."""
    result = {}
    for d in dicts:
        # Reuse merge_dicts so validation applies to every element of the sequence.
        result = merge_dicts(result, d)
    return result


def conflicting_keys(dict1, dict2):
    """Return the sorted keys whose values would actually change after merging."""
    shared = set(dict1) & set(dict2)
    changed = [key for key in shared if dict1[key] != dict2[key]]
    # Sorting by repr keeps the order stable even for mixed key types.
    return sorted(changed, key=repr)


def deep_merge(dict1, dict2):
    """Merge recursively: nested dictionaries are combined instead of replaced."""
    merged = dict(dict1)
    for key, value in dict2.items():
        current = merged.get(key)
        # Only recurse when both sides hold a dictionary for this key.
        if isinstance(current, dict) and isinstance(value, dict):
            merged[key] = deep_merge(current, value)
        else:
            merged[key] = value
    return merged


def format_dict(d):
    """Render a dict with keys in a deterministic order."""
    items = ", ".join("%r: %r" % (k, d[k]) for k in sorted(d, key=repr))
    return "{" + items + "}"


def format_merge_report(dict1, dict2):
    """Build a short human readable summary of one merge operation."""
    merged = merge_dicts(dict1, dict2)
    lines = ["merged: " + format_dict(merged)]
    overwritten = conflicting_keys(dict1, dict2)
    if overwritten:
        details = ", ".join("%r: %r -> %r" % (k, dict1[k], dict2[k]) for k in overwritten)
        lines.append("overwritten: " + details)
    else:
        # No shared key changed value, so the merge was a pure union.
        lines.append("overwritten: none")
    return "\n".join(lines)


def main():
    print(format_merge_report({'a': 1, 'b': 2}, {'b': 3, 'c': 4}))
    print(format_merge_report({'x': 10}, {'y': 20}))

    # Chained merges show that later dictionaries win over earlier ones.
    layers = [{'host': 'localhost', 'port': 80}, {'port': 8080}, {'debug': True}]
    print("chained: " + format_dict(merge_all(layers)))

    defaults = {'server': {'host': 'localhost', 'port': 80}, 'debug': False}
    overrides = {'server': {'port': 8080}, 'debug': True}
    # A flat merge would drop 'host', while the deep merge preserves it.
    print("flat: " + format_dict(merge_dicts(defaults, overrides)['server']))
    print("deep: " + format_dict(deep_merge(defaults, overrides)['server']))


if __name__ == "__main__":
    main()

