from datetime import date

DATE_FORMAT_HINT = "expected 'YYYY-MM-DD'"


def parse_date(date_str):
    """Convert a 'YYYY-MM-DD' string into a date object."""
    if not isinstance(date_str, str):
        raise TypeError("date must be given as a string, %s" % DATE_FORMAT_HINT)
    parts = date_str.strip().split("-")
    # A valid date has exactly three dash-separated components.
    if len(parts) != 3:
        raise ValueError("malformed date %r, %s" % (date_str, DATE_FORMAT_HINT))
    year_str, month_str, day_str = parts
    if len(year_str) != 4 or len(month_str) != 2 or len(day_str) != 2:
        raise ValueError("malformed date %r, %s" % (date_str, DATE_FORMAT_HINT))
    for part in parts:
        # Digits only: this rejects signs, spaces and unicode oddities.
        if not part.isdigit():
            raise ValueError("non numeric field in %r" % date_str)
    year, month, day = int(year_str), int(month_str), int(day_str)
    # The date constructor validates ranges and leap years for us.
    return date(year, month, day)


def days_between_dates(start_date_str, end_date_str):
    """Return end - start in whole days; negative when end precedes start."""
    start = parse_date(start_date_str)
    end = parse_date(end_date_str)
    return (end - start).days


def describe_gap(start_date_str, end_date_str):
    """Build a human readable sentence about the gap between two dates."""
    delta = days_between_dates(start_date_str, end_date_str)
    magnitude = abs(delta)
    # Singular or plural noun depending on the size of the gap.
    unit = "day" if magnitude == 1 else "days"
    if delta > 0:
        return "%s is %d %s after %s" % (end_date_str, magnitude, unit, start_date_str)
    if delta < 0:
        return "%s is %d %s before %s" % (end_date_str, magnitude, unit, start_date_str)
    return "%s and %s are the same day" % (start_date_str, end_date_str)


def report(pairs):
    """Describe every pair, keeping error messages inline with the results."""
    lines = []
    for start_date_str, end_date_str in pairs:
        try:
            lines.append(describe_gap(start_date_str, end_date_str))
        except (TypeError, ValueError) as exc:
            # Bad input should not abort the whole batch.
            lines.append("cannot compare %r and %r: %s" % (start_date_str, end_date_str, exc))
    return lines


def main():
    samples = [
        ("2023-01-01", "2023-01-05"),
        ("2023-01-01", "2022-12-25"),
        ("2024-02-28", "2024-03-01"),
        ("2023-06-15", "2023-06-15"),
        ("2023-02-29", "2023-03-01"),
        ("2023/07/04", "2023-07-05"),
    ]
    for line in report(samples):
        print(line)
    # The two documented examples double as a sanity check of the sign rule.
    print(days_between_dates("2023-01-01", "2023-01-05"))
    print(days_between_dates("2023-01-01", "2022-12-25"))


if __name__ == "__main__":
    main()

