def validate_interval(start, end, label):
    # Times must be plain integers; booleans are rejected because they are not hours.
    if isinstance(start, bool) or isinstance(end, bool):
        raise TypeError(f"{label}: hours must be integers, not booleans")
    if not isinstance(start, int) or not isinstance(end, int):
        raise TypeError(f"{label}: hours must be integers")
    # A 24-hour clock only allows values from 0 to 24 inclusive.
    if not (0 <= start <= 24) or not (0 <= end <= 24):
        raise ValueError(f"{label}: hours must lie between 0 and 24")
    # An interval that ends before it starts cannot be interpreted.
    if end < start:
        raise ValueError(f"{label}: end time {end} precedes start time {start}")
    return start, end


def has_overlap(task1_start, task1_end, task2_start, task2_end):
    """Return True if the two tasks share at least one hour of time."""
    validate_interval(task1_start, task1_end, "task1")
    validate_interval(task2_start, task2_end, "task2")
    # Touching at a boundary is not an overlap, so the comparison is strict.
    return task1_start < task2_end and task2_start < task1_end


def overlap_hours(task1_start, task1_end, task2_start, task2_end):
    """Return the number of hours the two tasks share (0 when disjoint)."""
    if not has_overlap(task1_start, task1_end, task2_start, task2_end):
        return 0
    latest_start = max(task1_start, task2_start)
    earliest_end = min(task1_end, task2_end)
    return earliest_end - latest_start


def format_hour(hour):
    # Hour 24 is the end of the day and is displayed as midnight.
    return "{:02d}:00".format(hour % 24)


def describe_pair(task1, task2):
    """Build a one-line report about the relation between two named tasks."""
    name1, start1, end1 = task1
    name2, start2, end2 = task2
    span1 = f"{format_hour(start1)}-{format_hour(end1)}"
    span2 = f"{format_hour(start2)}-{format_hour(end2)}"
    shared = overlap_hours(start1, end1, start2, end2)
    if shared:
        verdict = f"overlap of {shared}h"
    else:
        verdict = "no overlap"
    return f"{name1} ({span1}) vs {name2} ({span2}): {verdict}"


def find_conflicts(schedule):
    """Return every pair of tasks in the schedule that overlaps."""
    conflicts = []
    for i, first in enumerate(schedule):
        # Compare each task only with the ones after it to avoid duplicates.
        for second in schedule[i + 1:]:
            if has_overlap(first[1], first[2], second[1], second[2]):
                conflicts.append((first[0], second[0]))
    return conflicts


def main():
    schedule = [
        ("standup", 9, 10),
        ("review", 9, 12),
        ("lunch", 12, 13),
        ("workshop", 11, 14),
        ("retro", 10, 12),
    ]
    for i, task in enumerate(schedule):
        for other in schedule[i + 1:]:
            print(describe_pair(task, other))
    conflicts = find_conflicts(schedule)
    # Report the conflicting pairs so the schedule can be fixed.
    print(f"\n{len(conflicts)} conflicting pair(s):")
    for left, right in conflicts:
        print(f"  {left} <-> {right}")


if __name__ == "__main__":
    main()

