def validate_inputs(principal, rate, time):
    # Reject values that cannot describe a real loan or deposit.
    if principal < 0:
        raise ValueError("principal must be non-negative")
    if rate < 0:
        raise ValueError("rate must be non-negative")
    # Time is counted in whole years, so anything fractional is rejected.
    if not isinstance(time, int) or isinstance(time, bool):
        raise TypeError("time must be an integer number of years")
    if time < 0:
        raise ValueError("time must be non-negative")


def calculate_simple_interest(principal, rate, time):
    """Return the simple interest for the given principal, rate and years."""
    validate_inputs(principal, rate, time)
    # The rate arrives as a percentage, so scale it down to a fraction.
    return float(principal) * (float(rate) / 100.0) * time


def total_amount(principal, rate, time):
    """Return principal plus the accrued simple interest."""
    return float(principal) + calculate_simple_interest(principal, rate, time)


def yearly_schedule(principal, rate, time):
    """Build a list of (year, interest_so_far, balance) triples."""
    schedule = []
    for year in range(1, time + 1):
        interest = calculate_simple_interest(principal, rate, year)
        schedule.append((year, interest, float(principal) + interest))
    return schedule


def format_money(amount, symbol="$"):
    """Format a monetary amount with two decimals and thousands separators."""
    # Negative amounts are printed with the sign in front of the symbol.
    if amount < 0:
        return "-{}{:,.2f}".format(symbol, -amount)
    return "{}{:,.2f}".format(symbol, amount)


def format_report(principal, rate, time):
    """Return a multi-line report describing the growth of the deposit."""
    lines = ["Principal: {}  Rate: {}%  Years: {}".format(
        format_money(principal), rate, time)]
    schedule = yearly_schedule(principal, rate, time)
    # An empty schedule means the money was never invested for a full year.
    if not schedule:
        lines.append("  no interest accrues over a zero-year term")
    for year, interest, balance in schedule:
        lines.append("  year {:>2}: interest {:>12}  balance {:>12}".format(
            year, format_money(interest), format_money(balance)))
    lines.append("Total after {} years: {}".format(
        time, format_money(total_amount(principal, rate, time))))
    return "\n".join(lines)


def main():
    cases = [(1000, 5, 2), (500, 2.5, 10), (2500, 0, 3)]
    for principal, rate, time in cases:
        print(format_report(principal, rate, time))
        print()
    # Show that bad input is reported rather than silently accepted.
    try:
        calculate_simple_interest(1000, 5, 1.5)
    except TypeError as exc:
        print("rejected:", exc)


if __name__ == "__main__":
    main()

