def are_anagrams(str1, str2):
    # convert both strings to lowercase and remove spaces.
    s1 = str1.lower().replace(" ", "")
    s2 = str2.lower().replace(" ", "")

    # check if the lengths of the processed strings are different.
    if len(s1) != len(s2):
        return False # if lengths differ, they cannot be anagrams.

    # create character counts for the first string.
    char_count1 = {}
    for char in s1:
        char_count1[char] = char_count1.get(char, 0) + 1

    # compare character counts with the second string.
    for char in s2:
        if char not in char_count1:
            return False # character not found in the first string.
        char_count1[char] -= 1 # decrement count.
        if char_count1[char] < 0:
            return False # too many occurrences of this character.

    # all characters must have a count of 0 if they are anagrams.
    for count in char_count1.values():
        if count != 0:
            return False # remaining characters indicate not an anagram.

    return True # all checks passed, they are anagrams.

