        (['a', 'b'], ['c', 'd']),
        ([1, 1, 2, 2, 3], [2, 3, 3, 9]),
        ([[1, 2], [3]], [[3], [4]]),
        ([], [1, 2, 3]),
    ]

    for line in report(pairs):
        print(line)


if __name__ == "__main__":
    main()

