class Queue:
    """A first-in, first-out queue backed by a plain Python list."""

    def __init__(self, items=None):
        # Copy any initial items so the caller's list is never mutated.
        self._items = list(items) if items is not None else []

    def enqueue(self, item):
        # New arrivals always go to the back of the line.
        self._items.append(item)

    def dequeue(self):
        # An empty queue has nothing to hand back, so report None.
        if not self._items:
            return None
        # Removing index 0 keeps the front-to-back order intact.
        return self._items.pop(0)

    def peek(self):
        """Return the front item without removing it, or None if empty."""
        if not self._items:
            return None
        return self._items[0]

    def is_empty(self):
        return not self._items

    def __len__(self):
        return len(self._items)

    def __repr__(self):
        return "Queue({!r})".format(self._items)


def drain(queue):
    """Dequeue everything and return the items in the order they left."""
    served = []
    while True:
        item = queue.dequeue()
        # A None result is the signal that the queue ran dry.
        if item is None:
            break
        served.append(item)
    return served


def format_job(position, job):
    # Positions are shown one-based because that reads better in a report.
    return "{}. {} ({} pages)".format(position, job["name"], job["pages"])


def print_spooler_report(jobs):
    """Feed jobs through a queue and describe the order they are printed."""
    spooler = Queue()
    for job in jobs:
        # Reject malformed jobs early rather than failing mid-report.
        if "name" not in job or "pages" not in job:
            raise ValueError("each job needs a 'name' and a 'pages' entry")
        spooler.enqueue(job)

    lines = ["Queued jobs: {}".format(len(spooler))]
    head = spooler.peek()
    # Peeking must not consume the job, so the first line is still printed.
    lines.append("Next up: {}".format(head["name"]))

    total_pages = 0
    for position, job in enumerate(drain(spooler), start=1):
        total_pages += job["pages"]
        lines.append(format_job(position, job))

    lines.append("Total pages: {}".format(total_pages))
    return "\n".join(lines)


def main():
    jobs = [
        {"name": "report.pdf", "pages": 12},
        {"name": "invoice.txt", "pages": 2},
        {"name": "poster.png", "pages": 1},
    ]
    print(print_spooler_report(jobs))

    # An untouched queue still dequeues cleanly, returning None.
    print("Empty queue dequeue ->", Queue().dequeue())


if __name__ == "__main__":
    main()

