ABSOLUTE_ZERO_C = -273.15


def celsius_to_fahrenheit(celsius):
    """Convert a Celsius temperature to Fahrenheit."""
    # Reject values that cannot exist on the Kelvin scale.
    if celsius < ABSOLUTE_ZERO_C:
        raise ValueError("temperature below absolute zero: %r" % (celsius,))
    return float(celsius) * 9.0 / 5.0 + 32.0


def parse_celsius(text):
    """Read a Celsius value from a string such as '21.5' or ' -40 C '."""
    cleaned = text.strip()
    # A trailing unit marker is common in user input, so drop it.
    if cleaned.upper().endswith("C"):
        cleaned = cleaned[:-1].strip()
    if not cleaned:
        raise ValueError("no temperature given")
    return float(cleaned)


def format_conversion(celsius, decimals=1):
    """Render a single conversion as a human readable line."""
    fahrenheit = celsius_to_fahrenheit(celsius)
    # Keep both columns aligned so a list of results reads as a table.
    return "{0:>10.{2}f} C = {1:>10.{2}f} F".format(celsius, fahrenheit, decimals)


def conversion_table(start, stop, step=10.0):
    """Build conversion lines for every step from start up to stop."""
    if step <= 0:
        raise ValueError("step must be positive")
    lines = []
    current = float(start)
    while current <= float(stop) + 1e-9:
        lines.append(format_conversion(current))
        current += step
    return lines


def convert_all(texts):
    """Convert many textual inputs, reporting failures instead of crashing."""
    results = []
    for text in texts:
        try:
            celsius = parse_celsius(text)
            results.append(format_conversion(celsius))
        except ValueError as exc:
            # Bad input should not abort the whole batch.
            results.append("{0!r}: error ({1})".format(text, exc))
    return results


def main(argv):
    if len(argv) > 1:
        # Command line arguments are treated as temperatures to convert.
        for line in convert_all(argv[1:]):
            print(line)
        return 0
    print("Celsius to Fahrenheit")
    for line in conversion_table(-40, 100, 20):
        print(line)
    # The freezing and boiling points are the classic reference values.
    print("check:", celsius_to_fahrenheit(0), celsius_to_fahrenheit(100))
    return 0


if __name__ == "__main__":
    import sys

    sys.exit(main(sys.argv))

