def calculate_bmi(weight_kg: float, height_m: float) -> float:
    """Return the BMI for a given weight in kilograms and height in meters."""
    # Reject values that cannot describe a real person before dividing.
    if weight_kg <= 0:
        raise ValueError("weight_kg must be positive")
    if height_m <= 0:
        raise ValueError("height_m must be positive")
    bmi = weight_kg / (height_m * height_m)
    # Two decimals is the conventional precision for reported BMI values.
    return round(bmi, 2)


def classify_bmi(bmi: float) -> str:
    """Map a BMI value onto the standard WHO weight categories."""
    # Boundaries are upper-exclusive, matching the WHO tables.
    if bmi < 18.5:
        return "Underweight"
    if bmi < 25.0:
        return "Normal weight"
    if bmi < 30.0:
        return "Overweight"
    return "Obese"


def parse_measurement(text: str) -> float:
    """Convert a single user-supplied measurement into a float."""
    cleaned = text.strip().replace(",", ".")
    try:
        return float(cleaned)
    except ValueError:
        # Re-raise with a message that quotes the offending input.
        raise ValueError("not a number: %r" % text) from None


def describe(weight_kg: float, height_m: float) -> str:
    """Build a one-line human readable report for one person."""
    bmi = calculate_bmi(weight_kg, height_m)
    category = classify_bmi(bmi)
    return "{:.1f} kg / {:.2f} m -> BMI {:.2f} ({})".format(
        weight_kg, height_m, bmi, category
    )


def build_report(records):
    """Turn an iterable of (weight, height) string pairs into report lines."""
    lines = []
    for raw_weight, raw_height in records:
        try:
            weight = parse_measurement(raw_weight)
            height = parse_measurement(raw_height)
            lines.append(describe(weight, height))
        except ValueError as exc:
            # Bad rows are reported inline so the rest of the batch survives.
            lines.append("skipped ({})".format(exc))
    return lines


def main() -> None:
    measurements = [
        ("70", "1.75"),
        ("90", "1.80"),
        ("52,5", "1.68"),
        ("101", "1.62"),
        ("abc", "1.70"),
        ("64", "0"),
    ]
    for line in build_report(measurements):
        print(line)
    # Summarise only the rows that produced a usable BMI.
    valid = [pair for pair in measurements if not pair[0].isalpha()]
    total = 0.0
    counted = 0
    for raw_weight, raw_height in valid:
        height = parse_measurement(raw_height)
        if height <= 0:
            continue
        total += calculate_bmi(parse_measurement(raw_weight), height)
        counted += 1
    if counted:
        print("mean BMI over {} people: {:.2f}".format(counted, total / counted))


if __name__ == "__main__":
    main()

