    samples = ["Hello World", "Python", "rhythm", "AEIOU aeiou", ""]
    for sample in samples:
        print(describe(sample))
    grand_total = sum(count_vowels(sample) for sample in samples)
    print("Total vowels in %d samples: %d" % (len(samples), grand_total))


