import sys
import os


def iter_words(text):
    """Yield the whitespace-separated words of a chunk of text."""
    # Splitting with no argument collapses runs of spaces, tabs and newlines.
    for token in text.split():
        yield token


def count_words_in_file(filepath):
    """Return the total number of words in the plain text file at filepath."""
    total = 0
    # Reading line by line keeps memory use flat for large files.
    with open(filepath, "r", encoding="utf-8") as handle:
        for line in handle:
            total += sum(1 for _ in iter_words(line))
    return total


def count_lines_in_file(filepath):
    """Return the number of lines in the file, counting a final partial line."""
    lines = 0
    with open(filepath, "r", encoding="utf-8") as handle:
        for _ in handle:
            lines += 1
    return lines


def longest_word_in_file(filepath):
    """Return the longest word in the file, or an empty string if there is none."""
    longest = ""
    with open(filepath, "r", encoding="utf-8") as handle:
        for line in handle:
            for word in iter_words(line):
                # Ties are resolved in favour of the word seen first.
                if len(word) > len(longest):
                    longest = word
    return longest


def format_report(filepath):
    """Build a short human readable summary of a text file."""
    words = count_words_in_file(filepath)
    lines = count_lines_in_file(filepath)
    longest = longest_word_in_file(filepath)
    # Averaging only makes sense when the file actually holds at least one line.
    if lines:
        average = words / lines
    else:
        average = 0.0
    parts = [
        "File: {}".format(os.path.basename(filepath)),
        "Words: {}".format(words),
        "Lines: {}".format(lines),
        "Average words per line: {:.2f}".format(average),
    ]
    # An empty file has no longest word, so that row is left out entirely.
    if longest:
        parts.append("Longest word: {} ({} characters)".format(longest, len(longest)))
    return "\n".join(parts)


def main(argv):
    # Default to test.txt so the module can be run without arguments.
    paths = argv[1:] or ["test.txt"]
    for path in paths:
        if not os.path.isfile(path):
            print("Skipping {}: not a readable file".format(path), file=sys.stderr)
            continue
        print(format_report(path))
        # Separate consecutive reports with a blank line for readability.
        if path is not paths[-1]:
            print()
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))

