def calculate_discount_price(original_price, discount_percentage):
    """Return the price left after applying a percentage discount."""
    price = float(original_price)
    percent = float(discount_percentage)

    # Negative prices are meaningless for a sale item.
    if price < 0:
        raise ValueError("original_price must not be negative")

    # A discount outside 0..100 cannot be applied sensibly.
    if percent < 0 or percent > 100:
        raise ValueError("discount_percentage must be between 0 and 100")

    final_price = price * (1 - percent / 100)

    # Guard against tiny floating point residue such as -0.0 or 1e-15.
    if abs(final_price) < 1e-9:
        return 0.0
    return round(final_price, 2)


def savings(original_price, discount_percentage):
    """Return how much money the discount saves on this item."""
    return round(float(original_price) - calculate_discount_price(original_price, discount_percentage), 2)


def parse_offer(text):
    """Parse a line like 'Mug,12.50,15' into (name, price, percentage)."""
    parts = [field.strip() for field in text.split(",")]

    # The format is fixed, so reject anything with a different field count.
    if len(parts) != 3:
        raise ValueError("expected 'name,price,discount' but got: " + text)

    name, raw_price, raw_percent = parts

    # An unnamed product would produce useless report rows.
    if not name:
        raise ValueError("product name must not be empty")

    return name, float(raw_price), float(raw_percent)


def format_row(name, original_price, discount_percentage):
    """Build one aligned line of the discount report."""
    final_price = calculate_discount_price(original_price, discount_percentage)
    saved = savings(original_price, discount_percentage)
    return "{:<10} {:>8.2f} {:>6.1f}% {:>8.2f} {:>8.2f}".format(
        name, float(original_price), float(discount_percentage), final_price, saved
    )


def build_report(lines):
    """Turn raw offer lines into a header plus one row per valid offer."""
    header = "{:<10} {:>8} {:>7} {:>8} {:>8}".format("ITEM", "PRICE", "OFF", "FINAL", "SAVED")
    report = [header]

    for line in lines:
        stripped = line.strip()

        # Skip blank lines and comment lines in the input data.
        if not stripped or stripped.startswith("#"):
            continue

        try:
            name, price, percent = parse_offer(stripped)
        except ValueError as error:
            # Bad records are reported inline instead of aborting the run.
            report.append("SKIPPED: {}".format(error))
            continue

        report.append(format_row(name, price, percent))

    return report


def main():
    offers = [
        "# name,price,discount",
        "Mug,12.50,15",
        "Notebook,100,10",
        "Lamp,50,20",
        "Broken,abc,5",
        "Chair,89.99,0",
    ]

    for row in build_report(offers):
        print(row)

    # The two worked examples from the specification.
    print("check:", calculate_discount_price(100, 10), calculate_discount_price(50, 20))


if __name__ == "__main__":
    main()

