class BankAccount:
    def __init__(self, initial_balance):
        # Initializing the account with a starting balance.
        self.balance = initial_balance

    def deposit(self, amount):
        # Checking if the deposit amount is positive.
        if amount > 0:
            self.balance += amount
            # Returning True for a successful deposit.
            return True
        # Returning False for an invalid deposit amount.
        return False

    def withdraw(self, amount):
        # Ensuring the withdrawal amount is positive.
        if amount > 0:
            # Checking if there are sufficient funds for the withdrawal.
            if self.balance >= amount:
                self.balance -= amount
                # Indicating a successful withdrawal.
                return True
            else:
                # Insufficient funds, so withdrawal fails.
                return False
        # Returning False if the withdrawal amount is not positive.
        return False

