def update_inventory(inventory, item_name, quantity_change):
    """Apply a quantity change to an item and return the updated inventory."""
    if not isinstance(inventory, dict):
        raise TypeError("inventory must be a dictionary")
    if not isinstance(item_name, str) or not item_name:
        raise ValueError("item_name must be a non-empty string")
    if not isinstance(quantity_change, int) or isinstance(quantity_change, bool):
        raise TypeError("quantity_change must be an integer")

    # Unknown items start from an implicit stock of zero.
    current = inventory.get(item_name, 0)
    new_quantity = current + quantity_change

    # Stock can never drop below zero, so clamp the result.
    if new_quantity < 0:
        new_quantity = 0

    inventory[item_name] = new_quantity
    return inventory


def apply_transactions(inventory, transactions):
    """Apply a sequence of (item_name, quantity_change) pairs in order."""
    for item_name, quantity_change in transactions:
        # Each step mutates and returns the same dictionary.
        inventory = update_inventory(inventory, item_name, quantity_change)
    return inventory


def parse_transaction(line):
    """Turn a text line like 'apple +5' or 'banana -10' into a transaction."""
    parts = line.split()
    if len(parts) != 2:
        raise ValueError("expected '<item> <change>', got %r" % line)

    name, raw_change = parts
    try:
        change = int(raw_change)
    except ValueError:
        raise ValueError("%r is not an integer change" % raw_change)

    return name, change


def parse_transactions(lines):
    """Parse many lines, skipping blanks and '#' comments."""
    transactions = []
    for line in lines:
        stripped = line.strip()
        # Blank lines and comments carry no transaction data.
        if not stripped or stripped.startswith("#"):
            continue
        transactions.append(parse_transaction(stripped))
    return transactions


def format_report(inventory):
    """Render the inventory as aligned 'item: quantity' lines."""
    if not inventory:
        return "(empty inventory)"

    # Align the colons using the longest item name.
    width = max(len(name) for name in inventory)
    rows = []
    for name in sorted(inventory):
        quantity = inventory[name]
        flag = "  <-- out of stock" if quantity == 0 else ""
        rows.append("%-*s : %4d%s" % (width, name, quantity, flag))
    return "\n".join(rows)


def main():
    stock = {"apple": 10, "banana": 5, "cherry": 0}
    ledger = [
        "# morning deliveries",
        "apple +5",
        "cherry 24",
        "",
        "banana -10",
        "date +7",
    ]

    # The ledger is text, so it must be parsed before it can be applied.
    stock = apply_transactions(stock, parse_transactions(ledger))
    print(format_report(stock))


if __name__ == "__main__":
    main()

