ABSOLUTE_ZERO_C = -273.15

VALID_UNITS = ('C', 'F', 'K')


def _to_celsius(value, unit_from):
    # every conversion routes through Celsius as the pivot scale
    if unit_from == 'C':
        return float(value)
    if unit_from == 'F':
        return (float(value) - 32.0) * 5.0 / 9.0
    return float(value) + ABSOLUTE_ZERO_C


def _from_celsius(celsius, unit_to):
    # inverse of _to_celsius, so a round trip is the identity
    if unit_to == 'C':
        return celsius
    if unit_to == 'F':
        return celsius * 9.0 / 5.0 + 32.0
    return celsius - ABSOLUTE_ZERO_C


def convert_temperature(value, unit_from, unit_to):
    celsius = _to_celsius(value, unit_from)
    result = _from_celsius(celsius, unit_to)
    # collapse tiny floating point residue such as -1.4e-14 into a clean 0.0
    return float(round(result, 10))


def is_physical(value, unit):
    # a reading below absolute zero cannot describe a real system
    return _to_celsius(value, unit) >= ABSOLUTE_ZERO_C - 1e-9


def format_temperature(value, unit, decimals=2):
    symbol = '\u00b0' if unit in ('C', 'F') else ''
