# Additive string hashing plus a small bucket index built on top of it.


def simple_hash(s):
    if not isinstance(s, str):
        raise TypeError("simple_hash expects a string")
    total = 0
    # Adding code points makes the hash independent of character order.
    for ch in s:
        total += ord(ch)
    return total


def bucket_of(s, num_buckets):
    # A table with no slots leaves no valid index to return.
    if num_buckets < 1:
        raise ValueError("num_buckets must be at least 1")
    return simple_hash(s) % num_buckets


def build_index(words, num_buckets):
    # Every bucket exists up front, so empty ones keep their position.
    buckets = [[] for _ in range(num_buckets)]
    for word in words:
        buckets[bucket_of(word, num_buckets)].append(word)
    return buckets


def find_collisions(words):
    groups = {}
    for word in words:
        group = groups.setdefault(simple_hash(word), [])
        # Duplicated input words are not a collision, so keep each one once.
        if word not in group:
            group.append(word)
    # Only hash values shared by two or more distinct words are collisions.
    return {value: group for value, group in groups.items() if len(group) > 1}


def format_index(buckets):
    lines = []
    for number, words in enumerate(buckets):
        # Empty buckets are printed too, so the spread of the hash is visible.
        contents = ", ".join(sorted(words)) if words else "(empty)"
        lines.append("bucket {}: {}".format(number, contents))
    return "\n".join(lines)


def format_collisions(collisions):
    if not collisions:
        return "no collisions"
    lines = []
    # Sorting by hash value keeps the report stable between runs.
    for value in sorted(collisions):
        words = ", ".join(sorted(collisions[value]))
        lines.append("hash {} -> {}".format(value, words))
    return "\n".join(lines)


def main():
    samples = ["cat", "act", "tac", "dog", "bird", "", "hash"]
    for word in samples:
        print("{:>6} -> {}".format(repr(word), simple_hash(word)))
    print()
    print(format_index(build_index(samples, 5)))
    print()
    print(format_collisions(find_collisions(samples)))


if __name__ == "__main__":
    main()

