def group_by_type(items):
    """Group items by the name of their runtime type."""
    # Reject inputs that cannot be iterated over element by element.
    if not isinstance(items, (list, tuple)):
        raise TypeError("items must be a list or tuple")

    groups = {}
    for item in items:
        # The key is the bare class name, e.g. 'int' rather than "<class 'int'>".
        name = type(item).__name__
        groups.setdefault(name, []).append(item)
    return groups


def type_counts(items):
    """Return a mapping of type name to how many items have that type."""
    grouped = group_by_type(items)
    return {name: len(bucket) for name, bucket in grouped.items()}


def dominant_type(items):
    """Return the type name occurring most often, or None for an empty input."""
    counts = type_counts(items)
    if not counts:
        return None

    best_name = None
    best_count = -1
    for name, count in sorted(counts.items()):
        # Sorting first makes ties resolve alphabetically and deterministically.
        if count > best_count:
            best_name = name
            best_count = count
    return best_name


def format_groups(items, width=8):
    """Render the grouping as aligned text lines, most populous type first."""
    grouped = group_by_type(items)
    lines = []
    for name in sorted(grouped, key=lambda n: (-len(grouped[n]), n)):
        bucket = grouped[name]
        # Use repr so that strings stay distinguishable from numbers.
        shown = ", ".join(repr(value) for value in bucket)
        lines.append("{:<{w}} ({}) : {}".format(name, len(bucket), shown, w=width))
    return lines


def main():
    samples = [
        [1, 'a', 2.5, 'b', 3],
        [True, None, 0, 'x', (1, 2), [3], {'k': 1}, 4.0],
        [],
    ]

    for index, sample in enumerate(samples, start=1):
        print("Sample {}: {!r}".format(index, sample))
        for line in format_groups(sample):
            print("  " + line)

        leader = dominant_type(sample)
        # An empty sample has no groups at all, so report that explicitly.
        if leader is None:
            print("  no items to group")
        else:
            print("  most common type: {}".format(leader))
        print()

    # Booleans are their own type in Python and never merge into 'int'.
    mixed_flags = [True, False, 1, 0]
    print("Flag counts:", type_counts(mixed_flags))


if __name__ == "__main__":
    main()

